// FormatLicenseText indents raw license text per Debian RFC 822 / DEP-5 conventions:
// Each line must begin with a single space. Blank lines are represented by a single dot (" .").
func FormatLicenseText(rawText string) string {
	var b strings.Builder
	lines := strings.Split(strings.ReplaceAll(rawText, "\r\n", "\n"), "\n")
	for _, line := range lines {
		trimmed := strings.TrimRight(line, " \t\r")
		if strings.TrimSpace(trimmed) == "" {
			b.WriteString(" .\n")
		} else {
			b.WriteString(" " + trimmed + "\n")
		}
	}
	return b.String()
}

// ExtractCopyrightOwner constructs a DEP-5 compliant Copyright string from maintainer and year.
func ExtractCopyrightOwner(maintainer string, year int) string {
	trimmed := strings.TrimSpace(maintainer)
	if trimmed == "" {
		trimmed = "Package Authors and Contributors"
	}
	if year <= 0 {
		year = time.Now().UTC().Year()
	}
	// If maintainer already has a year like "2026 Name", avoid duplicating year
	if strings.Contains(trimmed, fmt.Sprintf("%d", year)) {
		return trimmed
	}
	return fmt.Sprintf("%d %s", year, trimmed)
}

// FindNoticeFile returns the relative path and contents of a NOTICE file in workspaceDir if present.
func FindNoticeFile(workspaceDir string) ([]byte, bool) {
	if workspaceDir == "" {
		workspaceDir = "."
	}
	candidates := []string{"NOTICE", "NOTICE.txt", "NOTICE.md"}
	for _, name := range candidates {
		p := filepath.Join(workspaceDir, name)
		if data, err := os.ReadFile(p); err == nil && len(data) > 0 {
			return data, true
		}
	}
	return nil, false
}

// SynthesizeCopyright generates a DEP-5 (Machine-Readable Copyright Format 1.0) document.
func SynthesizeCopyright(cfg *spec.CraftpackConfig, workspaceDir string, buildDate time.Time) ([]byte, error) {
	if cfg == nil {
		return nil, errors.New("craftpack config cannot be nil")
	}
	if strings.TrimSpace(cfg.Name) == "" {
		return nil, errors.New("package name cannot be empty")
	}

	year := buildDate.Year()
	if year <= 0 {
		year = time.Now().UTC().Year()
	}

	var b strings.Builder

	// Header stanza
	b.WriteString("Format: https://www.debian.org/doc/packaging-manuals/copyright-format/1.0/\n")
	b.WriteString("Upstream-Name: " + strings.TrimSpace(cfg.Name) + "\n")
	if strings.TrimSpace(cfg.Maintainer) != "" {
		b.WriteString("Upstream-Contact: " + strings.TrimSpace(cfg.Maintainer) + "\n")
	}
	if strings.TrimSpace(cfg.Homepage) != "" {
		b.WriteString("Source: " + strings.TrimSpace(cfg.Homepage) + "\n")
	}

	// Check for NOTICE file presence
	noticeContent, hasNotice := FindNoticeFile(workspaceDir)
	_ = noticeContent
	if hasNotice {
		b.WriteString("Comment:\n")
		b.WriteString(fmt.Sprintf(" This package includes third-party software components. Full attribution notices\n and third-party copyright grants are detailed in /usr/share/doc/%s/NOTICE.\n", cfg.Name))
	}
	b.WriteString("\n")

	// Files stanza
	b.WriteString("Files: *\n")
	b.WriteString("Copyright: " + ExtractCopyrightOwner(cfg.Maintainer, year) + "\n")
	licenseID := strings.TrimSpace(cfg.License)
	if licenseID == "" {
		licenseID = "Unknown"
	}
	b.WriteString("License: " + licenseID + "\n\n")

	// License stanza(s)
	// Track licenses to emit
	emittedLicenses := make(map[string]bool)

	// Primary license
	licenseText := resolveLicenseText(workspaceDir, licenseID)
	b.WriteString("License: " + licenseID + "\n")
	b.WriteString(FormatLicenseText(licenseText))
	emittedLicenses[licenseID] = true

	// Check for additional licenses in LICENSES/ directory
	licensesDir := filepath.Join(workspaceDir, "LICENSES")
	if entries, err := os.ReadDir(licensesDir); err == nil {
		var filenames []string
		for _, e := range entries {
			if !e.IsDir() {
				filenames = append(filenames, e.Name())
			}
		}
		sort.Strings(filenames)

		for _, fname := range filenames {
			if strings.HasPrefix(fname, ".") || strings.HasSuffix(fname, ".license") {
				continue
			}
			ext := filepath.Ext(fname)
			id := strings.TrimSuffix(fname, ext)
			if id == "" || emittedLicenses[id] {
				continue
			}
			licenseBody := resolveLicenseText(workspaceDir, id)
			b.WriteString("\nLicense: " + id + "\n")
			b.WriteString(FormatLicenseText(licenseBody))
			emittedLicenses[id] = true
		}
	}

	return []byte(b.String()), nil
}

// resolveLicenseText reads the license body or references common Debian licenses per Debian Policy §12.5.
func resolveLicenseText(workspaceDir, licenseID string) string {
	if notice, ok := commonLicenseNotice(licenseID); ok {
		return notice
	}

	if workspaceDir == "" {
		workspaceDir = "."
	}

	candidates := []string{
		filepath.Join(workspaceDir, "LICENSES", licenseID+".txt"),
		filepath.Join(workspaceDir, "LICENSES", licenseID),
		filepath.Join(workspaceDir, "LICENSE"),
		filepath.Join(workspaceDir, "LICENSE.txt"),
		filepath.Join(workspaceDir, "COPYING"),
	}

	for _, p := range candidates {
		if data, err := os.ReadFile(p); err == nil && len(data) > 0 {
			return string(data)
		}
	}

	// Fallback to common Debian reference notice
	return fmt.Sprintf("On Debian systems, the complete text of the %s license\ncan be found in `/usr/share/common-licenses/%s`.", licenseID, licenseID)
}

